-- Adds the อาหารสัตว์ (pet & animal feed) category to the shared catalog.

-- Shared catalog data (generated by scripts/catalog/catalog-to-sql.mjs)
ON DUPLICATE KEY UPDATE `barcode` = VALUES(`barcode`), `name` = VALUES(`name`), `brand` = VALUES(`brand`), `category` = VALUES(`category`), `unit` = VALUES(`unit`), `size` = VALUES(`size`), `source` = VALUES(`source`), `popularity` = VALUES(`popularity`);
